import Foundation

/// Room-noise beds and the reverb impulse response, synthesized deterministically
/// (seeded), so the committed WAVs can be regenerated byte for byte.
public enum Beds {
    public static let bedLevelDB = -30.0

    /// A desk / ceiling fan: brown-ish broadband rush, a blade-pass hum at 31 Hz with
    /// harmonics, a slow beat, motor whine at 120 Hz.
    public static func fan(seconds: Double, sampleRate: Int, seed: UInt64 = 0xFA11) -> [Float] {
        var rng = SeededRandom(seed: seed)
        let n = Int(seconds * Double(sampleRate))
        var lp1 = OnePole(cutoff: 900, sampleRate: sampleRate)
        var lp2 = OnePole(cutoff: 300, sampleRate: sampleRate)
        var hp = Biquad.highpass(cutoff: 40, sampleRate: sampleRate)
        var out = [Float](repeating: 0, count: n)
        let sr = Double(sampleRate)
        for i in 0..<n {
            let t = Double(i) / sr
            let white = rng.signed()
            let rush = 0.7 * lp1.lowpass(white) + 0.6 * lp2.lowpass(white)
            let blade = 0.05 * sin(2 * .pi * 31 * t) + 0.025 * sin(2 * .pi * 62 * t + 0.4) + 0.012 * sin(2 * .pi * 93 * t)
            let whine = 0.006 * sin(2 * .pi * 120 * t)
            let beat = 1 + 0.15 * sin(2 * .pi * 0.7 * t)
            out[i] = hp.process(Float(beat) * (rush + Float(blade + whine)))
        }
        return loopable(DSP.normalized(out, sampleRate: sampleRate, targetDB: bedLevelDB), sampleRate: sampleRate)
    }

    /// A kitchen: a tap running (band-passed noise with a gurgle), a fridge hum, and
    /// dish / cutlery clinks (decaying inharmonic partials) at random moments.
    public static func kitchen(seconds: Double, sampleRate: Int, seed: UInt64 = 0xC0C0) -> [Float] {
        var rng = SeededRandom(seed: seed)
        let n = Int(seconds * Double(sampleRate))
        let sr = Double(sampleRate)
        var water = Biquad.bandpass(center: 1800, q: 0.6, sampleRate: sampleRate)
        var water2 = Biquad.bandpass(center: 4200, q: 1.2, sampleRate: sampleRate)
        var gurgleLP = OnePole(cutoff: 3, sampleRate: sampleRate)
        var out = [Float](repeating: 0, count: n)
        // Tap runs for two stretches.
        let tapOn: [(Double, Double)] = [(1.0, 7.5), (12.0, 17.0)]
        for i in 0..<n {
            let t = Double(i) / sr
            let on = tapOn.contains { t >= $0.0 && t < $0.1 } ? 1.0 : 0.08
            let g = 0.6 + 2.0 * gurgleLP.lowpass(rng.signed())
            let w = water.process(rng.signed()) * 0.9 + water2.process(rng.signed()) * 0.4
            let hum = 0.01 * sin(2 * .pi * 60 * t) + 0.006 * sin(2 * .pi * 180 * t)
            out[i] = Float(on) * Float(g) * w + Float(hum)
        }
        // Clinks.
        var t = 0.4
        while t < seconds - 0.5 {
            let start = Int(t * sr)
            let base = 1800 + 2600 * rng.unit()
            let partials = [1.0, 2.76, 5.4]
            let amp = Float(0.25 + 0.35 * rng.unit())
            let decay = 18 + 20 * rng.unit()
            for k in 0..<Int(0.35 * sr) where start + k < n {
                let tt = Double(k) / sr
                var s = 0.0
                for (j, p) in partials.enumerated() { s += sin(2 * .pi * base * p * tt) / Double(j + 1) }
                out[start + k] += amp * Float(s * exp(-decay * tt))
            }
            t += 0.6 + 2.2 * rng.unit()
        }
        return loopable(DSP.normalized(out, sampleRate: sampleRate, targetDB: bedLevelDB), sampleRate: sampleRate)
    }

    /// A TV in the next room: several talkers (rendered elsewhere, e.g. `say`) summed
    /// at staggered offsets, band-limited like a small TV speaker (180 Hz – 5 kHz),
    /// with a soft music-like drone under it.
    public static func tv(talkers: [[Float]], seconds: Double, sampleRate: Int, seed: UInt64 = 0x7E1E) -> [Float] {
        var rng = SeededRandom(seed: seed)
        let n = Int(seconds * Double(sampleRate))
        var mix = [Float](repeating: 0, count: n)
        for (k, talker) in talkers.enumerated() where !talker.isEmpty {
            let gain = Float(DSP.linear(-3 * Double(k % 3)))
            var pos = Int(Double(sampleRate) * 0.3 * Double(k))
            // Loop each talker through the bed with short random gaps.
            while pos < n {
                for (i, v) in talker.enumerated() where pos + i < n { mix[pos + i] += gain * v }
                pos += talker.count + Int(Double(sampleRate) * (0.2 + 0.6 * rng.unit()))
            }
        }
        var hp = Biquad.highpass(cutoff: 180, sampleRate: sampleRate)
        var lp = OnePole(cutoff: 5000, sampleRate: sampleRate)
        let sr = Double(sampleRate)
        for i in 0..<n {
            let t = Double(i) / sr
            let drone = 0.02 * sin(2 * .pi * 220 * t) * (0.5 + 0.5 * sin(2 * .pi * 0.25 * t))
                + 0.015 * sin(2 * .pi * 277.2 * t) + 0.012 * sin(2 * .pi * 329.6 * t)
            mix[i] = lp.lowpass(hp.process(mix[i])) + Float(drone)
        }
        return loopable(DSP.normalized(mix, sampleRate: sampleRate, targetDB: bedLevelDB), sampleRate: sampleRate)
    }

    /// A small living room: direct sound, a few early reflections, then an
    /// exponentially decaying diffuse tail (RT60 ≈ `rt60`). Peak-normalized to 1;
    /// the echo path applies its own gain.
    public static func roomImpulse(rt60: Double = 0.35, seconds: Double = 0.4, sampleRate: Int, seed: UInt64 = 0x1A0) -> [Float] {
        var rng = SeededRandom(seed: seed)
        let n = Int(seconds * Double(sampleRate))
        var h = [Float](repeating: 0, count: n)
        h[0] = 1
        for (ms, g) in [(3.1, 0.55), (6.8, -0.4), (11.3, 0.32), (17.9, -0.22), (23.0, 0.18)] {
            let k = Int(ms / 1000 * Double(sampleRate))
            if k < n { h[k] += Float(g) }
        }
        let tau = rt60 / log(1000)          // amplitude e-fold time for a 60 dB decay
        var lp = OnePole(cutoff: 6000, sampleRate: sampleRate)
        let start = Int(0.005 * Double(sampleRate))
        for i in start..<n {
            let t = Double(i) / Double(sampleRate)
            h[i] += 0.35 * lp.lowpass(rng.signed()) * Float(exp(-t / tau))
        }
        let p = DSP.peak(h)
        return DSP.scaled(h, by: 1 / max(p, 1e-9))
    }

    /// 50 ms crossfade of the end into the start, so looping has no click.
    static func loopable(_ x: [Float], sampleRate: Int) -> [Float] {
        let f = min(Int(0.05 * Double(sampleRate)), x.count / 4)
        guard f > 0 else { return x }
        var y = Array(x[0..<(x.count - f)])
        for i in 0..<f {
            let g = Float(i) / Float(f)
            y[i] = y[i] * g + x[x.count - f + i] * (1 - g)
        }
        return y
    }
}
